def cab(y,cross,lbl,c):
    s=f'<rect x="60" y="{y}" width="30" height="70" rx="5" fill="var(--line)"/><rect x="270" y="{y}" width="30" height="70" rx="5" fill="var(--line)"/>'
    pins=[1,2,3,6]
    for k,p in enumerate(pins):
        y1=y+10+k*16;q=pins[[2,3,0,1][k]] if cross else p;y2=y+10+pins.index(q)*16
        s+=f'<path d="M90 {y1}C180 {y1} 180 {y2} 270 {y2}" stroke="{c if k<2 else "#9aa4b2"}" stroke-width="3" fill="none"/>'+num(75,y1+5,p,"var(--ink)",11)+num(285,y2+5,q,"var(--ink)",11)
    return s+lab(180,y-6,lbl,13.5,800,c)
